create table if not exists characters (id uuid primary key default gen_random_uuid(), name text not null, age text, personality text, physical_appearance text, outfit text, dominant_colors text, signature_pose text, accessories text, fixed_visual_rules text, negative_prompt text, reference_images text[] default '{}', created_at timestamptz default now());
create table if not exists style_presets (id uuid primary key default gen_random_uuid(), name text not null, description text not null, negative_prompt text, created_at timestamptz default now());
create table if not exists reference_images (id uuid primary key default gen_random_uuid(), name text not null, type text not null, url text not null, storage_path text, metadata jsonb default '{}', created_at timestamptz default now());
create table if not exists comic_chapters (id uuid primary key default gen_random_uuid(), title text not null, chapter_number int not null, created_at timestamptz default now());
create table if not exists comic_scenes (id uuid primary key default gen_random_uuid(), chapter_id uuid references comic_chapters(id) on delete cascade, title text not null, scene_number int not null, summary text, created_at timestamptz default now());
create table if not exists comic_panels (id uuid primary key default gen_random_uuid(), scene_id uuid references comic_scenes(id) on delete cascade, panel_number int not null, prompt text not null, negative_prompt text, image_url text, metadata jsonb default '{}', created_at timestamptz default now());
create table if not exists generation_history (id uuid primary key default gen_random_uuid(), panel_id uuid references comic_panels(id) on delete set null, prompt text not null, image_url text, metadata jsonb default '{}', created_at timestamptz default now());
